    &:has(.card-columns__left .is-expanded, .card-columns__right .is-expanded) {
      grid-template-columns: auto auto auto;

      @media (min-width: 640px) {
        grid-template-columns: auto var(--column-width-expanded) auto;
      }
    }

    &:has(.cards) {
      block-size: 100%;
